    "code": "// 🎆 ئاتەشبازی — کلیک بکە لە هەر شوێنێک بۆ تەقاندنەوە\nقەبارە(٥٠٠، ٣٥٠)\nگۆڕاو پارچەکان = []\nگۆڕاو کات = ٠\n\nکار بتەقێنە(x، y) {\n  نەگۆڕ ڕەنگ = هەڕەمەکی(٠، ٣٦٠)\n  بۆ i لە ١ تا ٦٠ {\n    نەگۆڕ گ = هەڕەمەکی(٠، ٣٦٠) * پای / ١٨٠\n    نەگۆڕ خ = هەڕەمەکی(١، ٦)\n    پارچەکان.زیادبکە({ x: x، y: y، vx: کۆسینۆس(گ) * خ، vy: سینۆس(گ) * خ، ژیان: ٦٠، ڕەنگ: ڕەنگ + هەڕەمەکی(-٢٠، ٢٠) })\n  }\n}\n\nیاریبکە(() => {\n  کات += ١\n  ئەگەر کلیککراوە() { بتەقێنە(ماوسX()، ماوسY()) }\n  ئەگەر کات % ٥٠ == ٠ { بتەقێنە(هەڕەمەکی(٥٠، ٤٥٠)، هەڕەمەکی(٣٠، ١٩٠)) }\n\n  پاشبنەمابکە(ڕەنگی(٥، ٥، ١٥))\n  گۆڕاو زیندوو = []\n  بۆ هەر پ لە پارچەکان {\n    پ.x += پ.vx\n    پ.y += پ.vy\n    پ.vy += ٠٫٠٦\n    پ.ژیان -= ١\n    ئەگەر پ.ژیان > ٠ {\n      ڕەنگبکە(پەلکەزێڕینە(پ.ڕەنگ، پ.ژیان / ٦٠))\n      بازنە(پ.x، پ.y، ٣)\n      زیندوو.زیادبکە(پ)\n    }\n  }\n  پارچەکان = زیندوو\n  ڕەنگبکە(ڕەنگی(٢٥٥، ٢٥٥، ٢٥٥، ٠٫٥))\n  نووسین(\"کلیک بکە!\", ٢٠٠، ٣٣٠، ١٨)\n})\n"
