    "code": "// یاری: تێتریس — ← → بجووڵێنە، ↑ بسووڕێنە، ↓ خێراتر، بۆشایی = دەستبەجێ دابکەوێت. ڕیزی پڕ دەسڕێتەوە!\nقەبارە(٣٤٠، ٤٨٠)\nنەگۆڕ شێوەکان = [\n  [[٠، ٠]، [١، ٠]، [٢، ٠]، [٣، ٠]]،\n  [[٠، ٠]، [١، ٠]، [٠، ١]، [١، ١]]،\n  [[٠، ٠]، [١، ٠]، [٢، ٠]، [١، ١]]،\n  [[١، ٠]، [٢، ٠]، [٠، ١]، [١، ١]]،\n  [[٠، ٠]، [١، ٠]، [١، ١]، [٢، ١]]،\n  [[٠، ٠]، [٠، ١]، [١، ١]، [٢، ١]]،\n  [[٢، ٠]، [٠، ١]، [١، ١]، [٢، ١]]،\n]\nگۆڕاو تەخت = []\nگۆڕاو پارچە = هیچ\nگۆڕاو دواتر = هەڕەمەکی(٠، ٦)\nگۆڕاو خاڵ = ٠\nگۆڕاو ڕیزەکان = ٠\nگۆڕاو کات = ٠\nگۆڕاو مردووە = هەڵە\nگۆڕاو پێشووسەرەوە = هەڵە\nگۆڕاو پێشووبۆشایی = هەڵە\n\nکار تەختی_نوێ() {\n  تەخت = []\n  بۆ y لە ١ تا ٢٠ {\n    نەگۆڕ ڕ = []\n    بۆ x لە ١ تا ١٠ { ڕ.زیادبکە(٠) }\n    تەخت.زیادبکە(ڕ)\n  }\n}\n\nکار پارچەی_نوێ() {\n  پارچە = { خانەکان: شێوەکان[دواتر]، x: ٣، y: ٠، ڕەنگ: دواتر * ٥٠ + ٢٠ }\n  دواتر = هەڕەمەکی(٠، ٦)\n  ئەگەر نەک دەگونجێت(پارچە.خانەکان، پارچە.x، پارچە.y) { مردووە = ڕاست }\n}\n\nکار دەگونجێت(خانەکان، px، py) {\n  بۆ هەر خ لە خانەکان {\n    نەگۆڕ x = px + خ[٠]\n    نەگۆڕ y = py + خ[١]\n    ئەگەر x < ٠ یان x > ٩ یان y > ١٩ { گەڕێنەوە هەڵە }\n    ئەگەر y >= ٠ و تەخت[y][x] != ٠ { گەڕێنەوە هەڵە }\n  }\n  گەڕێنەوە ڕاست\n}\n\nکار دابنێ() {\n  بۆ هەر خ لە پارچە.خانەکان { تەخت[پارچە.y + خ[١]][پارچە.x + خ[٠]] = پارچە.ڕەنگ }\n  نەگۆڕ ماوە = تەخت.پاڵاوتن(ڕ => ڕ.پاڵاوتن(v => v == ٠).درێژی > ٠)\n  نەگۆڕ سڕدراو = ٢٠ - ماوە.درێژی\n  گۆڕاو تەختی_ماوە = ماوە\n  هەتا تەختی_ماوە.درێژی < ٢٠ {\n    نەگۆڕ بەتاڵ = []\n    بۆ x لە ١ تا ١٠ { بەتاڵ.زیادبکە(٠) }\n    تەختی_ماوە = [بەتاڵ، ...تەختی_ماوە]\n  }\n  تەخت = تەختی_ماوە\n  ڕیزەکان += سڕدراو\n  خاڵ += [٠، ١٠٠، ٣٠٠، ٥٠٠، ٨٠٠][سڕدراو]\n  پارچەی_نوێ()\n}\n\nکار بسووڕێنە() {\n  نەگۆڕ س = پارچە.خانەکان.نەخشە(خ => [-خ[١]، خ[٠]])\n  نەگۆڕ کەمX = گەورەترین(...س.نەخشە(خ => -خ[٠]))\n  نەگۆڕ کەمY = گەورەترین(...س.نەخشە(خ => -خ[١]))\n  نەگۆڕ ڕاستکراو = س.نەخشە(خ => [خ[٠] + کەمX، خ[١] + کەمY])\n  بۆ هەر ڕاگوێزان لە [٠، -١، ١] {\n    ئەگەر دەگونجێت(ڕاستکراو، پارچە.x + ڕاگوێزان، پارچە.y) {\n      پارچە.خانەکان = ڕاستکراو؛ پارچە.x += ڕاگوێزان\n      گەڕێنەوە\n    }\n  }\n}\n\nتەختی_نوێ()\nپارچەی_نوێ()\n\nیاریبکە(() => {\n  کات += ١\n  نەگۆڕ بۆشایی = کلیل(\"بۆشایی\")\n  نەگۆڕ سەرەوە = کلیل(\"سەرەوە\")\n  ئەگەر مردووە {\n    ئەگەر کلیککراوە() { تەختی_نوێ()؛ خاڵ = ٠؛ ڕیزەکان = ٠؛ مردووە = هەڵە؛ پارچەی_نوێ() }\n  } ئەگەرنا {\n    ئەگەر کات % ٥ == ٠ {\n      ئەگەر کلیل(\"چەپ\") و دەگونجێت(پارچە.خانەکان، پارچە.x - ١، پارچە.y) { پارچە.x -= ١ }\n      ئەگەر کلیل(\"ڕاست\") و دەگونجێت(پارچە.خانەکان، پارچە.x + ١، پارچە.y) { پارچە.x += ١ }\n    }\n    ئەگەر سەرەوە و نەک پێشووسەرەوە { بسووڕێنە() }\n    ئەگەر بۆشایی و نەک پێشووبۆشایی {\n      هەتا دەگونجێت(پارچە.خانەکان، پارچە.x، پارچە.y + ١) { پارچە.y += ١ }\n      دابنێ()\n    } ئەگەرنا {\n      نەگۆڕ خێرایی = خوارکە(گەورەترین(٦، ٣٠ - ڕیزەکان * ٢))\n      ئەگەر کات % (کلیل(\"خوارەوە\") ? ٢ : خێرایی) == ٠ {\n        ئەگەر دەگونجێت(پارچە.خانەکان، پارچە.x، پارچە.y + ١) { پارچە.y += ١ } ئەگەرنا { دابنێ() }\n      }\n    }\n  }\n  پێشووسەرەوە = سەرەوە\n  پێشووبۆشایی = بۆشایی\n\n  پاشبنەمابکە(ڕەنگی(١٥، ٢٠، ٣٥))\n  ڕەنگبکە(ڕەنگی(٢٥، ٣٠، ٥٠))\n  لاکێش(٠، ٠، ٢٤٠، ٤٨٠)\n  بۆ y لە ٠ تا ١٩ {\n    بۆ x لە ٠ تا ٩ {\n      ئەگەر تەخت[y][x] != ٠ {\n        ڕەنگبکە(پەلکەزێڕینە(تەخت[y][x]))\n        لاکێش(x * ٢٤ + ١، y * ٢٤ + ١، ٢٢، ٢٢)\n      }\n    }\n  }\n  ئەگەر پارچە و نەک مردووە {\n    ڕەنگبکە(پەلکەزێڕینە(پارچە.ڕەنگ))\n    بۆ هەر خ لە پارچە.خانەکان { لاکێش((پارچە.x + خ[٠]) * ٢٤ + ١، (پارچە.y + خ[١]) * ٢٤ + ١، ٢٢، ٢٢) }\n  }\n  ڕەنگبکە(\"سپی\")\n  نووسین(\"خاڵ\", ٢٥٥، ٣٥، ١٨)\n  نووسین(خاڵ، ٢٥٥، ٦٠، ٢٤)\n  نووسین(\"ڕیز\", ٢٥٥، ١٠٠، ١٨)\n  نووسین(ڕیزەکان، ٢٥٥، ١٢٥، ٢٤)\n  نووسین(\"دواتر\", ٢٥٥، ١٧٠، ١٨)\n  ڕەنگبکە(پەلکەزێڕینە(دواتر * ٥٠ + ٢٠))\n  بۆ هەر خ لە شێوەکان[دواتر] { لاکێش(٢٥٥ + خ[٠] * ١٨، ١٩٠ + خ[١] * ١٨، ١٦، ١٦) }\n  ئەگەر مردووە {\n    ڕەنگبکە(ڕەنگی(٠، ٠، ٠، ٠٫٦))\n    لاکێش(٠، ٠، ٢٤٠، ٤٨٠)\n    ڕەنگبکە(\"سپی\")\n    نووسین(\"تەواو بوو!\", ٥٠، ٢١٠، ٣٠)\n    نووسین(\"کلیک = دووبارە\", ٥٠، ٢٥٠، ٢٠)\n  }\n})\n"
