    "code": "// یاری: بۆقە — بە تیرەکان لە ڕێگا و ڕووباردا بپەڕەوە بۆ سەرەوە. ئوتومبێلەکان مەکەوە، لەسەر داری ڕووبار بمێنەوە!\nقەبارە(٤٠٠، ٤٧٠)\n// هەر هێڵێک: ڕیز، خێرایی، پانی شتەکان، جۆر (\"ئوتومبێل\" یان \"دار\")\nنەگۆڕ هێڵەکان = [\n  { ڕیز: ١، خ: ١٫٢، پان: ١٢٠، جۆر: \"دار\" }،\n  { ڕیز: ٢، خ: -٢، پان: ٨٠، جۆر: \"دار\" }،\n  { ڕیز: ٣، خ: ١٫٦، پان: ١٠٠، جۆر: \"دار\" }،\n  { ڕیز: ٥، خ: -٢٫٥، پان: ٥٠، جۆر: \"ئوتومبێل\" }،\n  { ڕیز: ٦، خ: ٣، پان: ٦٠، جۆر: \"ئوتومبێل\" }،\n  { ڕیز: ٧، خ: -١٫٨، پان: ٥٠، جۆر: \"ئوتومبێل\" }،\n  { ڕیز: ٨، خ: ٣٫٥، پان: ٦٠، جۆر: \"ئوتومبێل\" }،\n]\nنەگۆڕ شتەکان = []\nهێڵەکان.بۆهەریەک((ه، i) => {\n  بۆ k لە ٠ تا ٢ { شتەکان.زیادبکە({ هێڵ: ه، x: k * ١٦٠ + i * ٣٧ }) }\n})\nگۆڕاو بۆقە = { x: ١٨٠، ڕیز: ١٠ }\nگۆڕاو ژیان = ٣\nگۆڕاو خاڵ = ٠\nگۆڕاو پێشوو = هەڵە\nگۆڕاو مردووە = هەڵە\n\nکار دووبارە() { بۆقە = { x: ١٨٠، ڕیز: ١٠ } }\nکار مردن() { ژیان -= ١؛ دووبارە() }\n\nیاریبکە(() => {\n  نەگۆڕ ئا = کلیل(\"چەپ\") ? \"چ\" : کلیل(\"ڕاست\") ? \"ڕ\" : کلیل(\"سەرەوە\") ? \"س\" : کلیل(\"خوارەوە\") ? \"خ\" : \"\"\n  ئەگەر ژیان > ٠ {\n    ئەگەر ئا != \"\" و نەک پێشوو {\n      ئەگەر ئا == \"چ\" { بۆقە.x -= ٤٠ }\n      ئەگەر ئا == \"ڕ\" { بۆقە.x += ٤٠ }\n      ئەگەر ئا == \"س\" { بۆقە.ڕیز -= ١ }\n      ئەگەر ئا == \"خ\" { بۆقە.ڕیز = بچووکترین(١٠، بۆقە.ڕیز + ١) }\n    }\n    بۆ هەر ش لە شتەکان {\n      ش.x += ش.هێڵ.خ\n      ئەگەر ش.هێڵ.خ > ٠ و ش.x > ٤٠٠ { ش.x = -ش.هێڵ.پان }\n      ئەگەر ش.هێڵ.خ < ٠ و ش.x < -ش.هێڵ.پان { ش.x = ٤٠٠ }\n    }\n    نەگۆڕ لەسەرداری = []\n    بۆ هەر ش لە شتەکان {\n      ئەگەر ش.هێڵ.ڕیز == بۆقە.ڕیز {\n        نەگۆڕ بۆقەناوەند = بۆقە.x + ١٥\n        ئەگەر بۆقەناوەند > ش.x و بۆقەناوەند < ش.x + ش.هێڵ.پان {\n          ئەگەر ش.هێڵ.جۆر == \"ئوتومبێل\" { مردن() } ئەگەرنا { لەسەرداری.زیادبکە(ش) }\n        }\n      }\n    }\n    ئەگەر بۆقە.ڕیز >= ١ و بۆقە.ڕیز <= ٣ {\n      ئەگەر لەسەرداری.درێژی > ٠ { بۆقە.x += لەسەرداری[٠].هێڵ.خ } ئەگەرنا { مردن() }\n    }\n    ئەگەر بۆقە.x < ٠ یان بۆقە.x > ٣٧٠ { بۆقە.x = سنوور(بۆقە.x، ٠، ٣٧٠)؛ ئەگەر بۆقە.ڕیز >= ١ و بۆقە.ڕیز <= ٣ { مردن() } }\n    ئەگەر بۆقە.ڕیز == ٠ { خاڵ += ١٠؛ دووبارە() }\n  } ئەگەرنا ئەگەر کلیککراوە() { ژیان = ٣؛ خاڵ = ٠؛ دووبارە() }\n  پێشوو = ئا != \"\"\n\n  پاشبنەمابکە(ڕەنگی(٢٠، ٤٠، ٢٥))\n  // ڕووبار\n  ڕەنگبکە(ڕەنگی(٣٠، ٨٠، ١٨٠))\n  لاکێش(٠، ٧٠، ٤٠٠، ١٢٠)\n  // ڕێگا\n  ڕەنگبکە(ڕەنگی(٤٠، ٤٠، ٤٨))\n  لاکێش(٠، ٢٣٠، ٤٠٠، ١٦٠)\n  ڕەنگبکە(ڕەنگی(٩٠، ١٧٠، ٨٠))\n  لاکێش(٠، ٣٠، ٤٠٠، ٤٠)؛ لاکێش(٠، ١٩٠، ٤٠٠، ٤٠)؛ لاکێش(٠، ٤٣٠، ٤٠٠، ٤٠)\n  بۆ هەر ش لە شتەکان {\n    نەگۆڕ y = ش.هێڵ.ڕیز * ٤٠ + ٣٠\n    ئەگەر ش.هێڵ.جۆر == \"دار\" {\n      ڕەنگبکە(\"قاوەیی\")\n      لاکێش(ش.x، y + ٤، ش.هێڵ.پان، ٣٢)\n    } ئەگەرنا {\n      ڕەنگبکە(ش.هێڵ.خ > ٠ ? \"سوور\" : \"نارنجی\")\n      لاکێش(ش.x، y + ٦، ش.هێڵ.پان، ٢٨)\n      ڕەنگبکە(\"سپی\")\n      لاکێش(ش.x + ش.هێڵ.پان * ٠٫٦، y + ١٠، ش.هێڵ.پان * ٠٫٢، ٢٠)\n    }\n  }\n  ئەگەر ژیان > ٠ {\n    نەگۆڕ y = بۆقە.ڕیز * ٤٠ + ٣٠\n    ڕەنگبکە(\"سەوز\")\n    لاکێش(بۆقە.x + ٤، y + ٦، ٢٢، ٢٨)\n    بازنە(بۆقە.x + ١٥، y + ٨، ٨)\n    ڕەنگبکە(\"سپی\")\n    بازنە(بۆقە.x + ١١، y + ٥، ٣)؛ بازنە(بۆقە.x + ٢٠، y + ٥، ٣)\n  }\n  ڕەنگبکە(\"سپی\")\n  نووسین(\"خاڵ: \" + خاڵ، ١٠، ٢٢، ١٨)\n  نووسین(\"❤ \" + ژیان، ٣٤٠، ٢٢، ١٨)\n  ئەگەر ژیان <= ٠ {\n    ڕەنگبکە(ڕەنگی(٠، ٠، ٠، ٠٫٦))\n    لاکێش(٠، ٠، ٤٠٠، ٤٧٠)\n    ڕەنگبکە(\"سپی\")\n    نووسین(\"تەواو بوو! خاڵ: \" + خاڵ، ١٠٠، ٢٢٠، ٢٦)\n    نووسین(\"کلیک = دووبارە\", ١٣٠، ٢٦٠، ٢٠)\n  }\n})\n"
