    "thumb": 40,
    "code": "// یاری: باز بدە ⬆ — بە خۆی باز دەدات! بە ← → یان ماوس بیجووڵێنە و بەرەو سەرەوە بڕۆ. نەکەویتە خوارەوە\nقەبارە(٣٢٠، ٤٨٠)\nگۆڕاو x = ١٤٠\nگۆڕاو y = ٣٠٠\nگۆڕاو vy = -١٢\nگۆڕاو پلەکان = []\nگۆڕاو بەرزی = ٠\nگۆڕاو مردووە = هەڵە\nگۆڕاو بەرزترین = ٠\n\nکار دەستپێکردن() {\n  x = ١٤٠؛ y = ٣٠٠؛ vy = -١٢؛ بەرزی = ٠؛ مردووە = هەڵە\n  پلەکان = [{ x: ١٢٠، y: ٣٨٠، جۆر: ٠ }]\n  بۆ i لە ١ تا ٨ { پلەکان.زیادبکە({ x: هەڕەمەکی(٠، ٢٥٠)، y: ٣٨٠ - i * ٦٠، جۆر: هەڕەمەکی(٠، ٤) == ٠ ? ١ : ٠ }) }\n}\nدەستپێکردن()\n\nیاریبکە(() => {\n  ئەگەر نەک مردووە {\n    ئەگەر کلیل(\"چەپ\") { x -= ٦ }\n    ئەگەر کلیل(\"ڕاست\") { x += ٦ }\n    ئەگەر ماوسX() >= ٠ { x += (ماوسX() - ٢٠ - x) * ٠٫١ }\n    x = ((x + ٢٠) % ٣٢٠ + ٣٢٠) % ٣٢٠ - ٢٠\n    نەگۆڕ پێشوو = y + ٤٠\n    vy += ٠٫٦\n    y += vy\n    ئەگەر vy > ٠ {\n      بۆ هەر پ لە پلەکان {\n        ئەگەر پێشوو <= پ.y + ٣ و y + ٤٠ >= پ.y و x + ٣٠ > پ.x و x + ١٠ < پ.x + ٧٠ { vy = پ.جۆر == ١ ? -١٧ : -١٢ }\n      }\n    }\n    // کامێرا\n    ئەگەر y < ٢٠٠ {\n      نەگۆڕ جیاوازی = ٢٠٠ - y\n      y = ٢٠٠\n      بەرزی += جیاوازی\n      بۆ هەر پ لە پلەکان { پ.y += جیاوازی }\n    }\n    پلەکان = پلەکان.پاڵاوتن(پ => پ.y < ٤٩٠)\n    هەتا پلەکان.درێژی < ٩ {\n      گۆڕاو بەرزترینپلە = ٥٠٠\n      بۆ هەر پ لە پلەکان { بەرزترینپلە = بچووکترین(بەرزترینپلە، پ.y) }\n      پلەکان.زیادبکە({ x: هەڕەمەکی(٠، ٢٥٠)، y: بەرزترینپلە - هەڕەمەکی(٥٠، ٨٠)، جۆر: هەڕەمەکی(٠، ٥) == ٠ ? ١ : ٠ })\n    }\n    ئەگەر y > ٥٠٠ { مردووە = ڕاست }\n    بەرزترین = گەورەترین(بەرزترین، خوارکە(بەرزی))\n  } ئەگەرنا ئەگەر کلیککراوە() { دەستپێکردن() }\n\n  پاشبنەمابکە(ڕەنگی(٢٣٠، ٢٤٥، ٢٥٥))\n  ڕەنگبکە(ڕەنگی(٢٠٠، ٢٢٠، ٢٤٠))\n  بۆ i لە ٠ تا ١٥ { لاکێش(٠، i * ٣٠، ٣٢٠، ١) }\n  بۆ هەر پ لە پلەکان {\n    ڕەنگبکە(پ.جۆر == ١ ? \"نارنجی\" : \"سەوز\")\n    لاکێش(پ.x، پ.y، ٧٠، ١٢)\n    ئەگەر پ.جۆر == ١ { ڕەنگبکە(\"سپی\")؛ لاکێش(پ.x + ٢٠، پ.y + ٣، ٣٠، ٣) }\n  }\n  ڕەنگبکە(\"زەرد\")\n  لاکێش(x + ١٠، y، ٣٠، ٣٨)\n  ڕەنگبکە(\"سپی\")\n  بازنە(x + ٢٠، y + ١٠، ٦)؛ بازنە(x + ٣٢، y + ١٠، ٦)\n  ڕەنگبکە(\"ڕەش\")\n  بازنە(x + ٢٢، y + ١٠، ٢)؛ بازنە(x + ٣٤، y + ١٠، ٢)\n  ڕەنگبکە(\"ڕەش\")\n  نووسین(\"بەرزی: \" + خوارکە(بەرزی)، ١٠، ٢٨، ٢٠)\n  نووسین(\"باشترین: \" + بەرزترین، ٢٠٠، ٢٨، ١٦)\n  ئەگەر مردووە {\n    ڕەنگبکە(ڕەنگی(٠، ٠، ٠، ٠٫٦))\n    لاکێش(٠، ٠، ٣٢٠، ٤٨٠)\n    ڕەنگبکە(\"سپی\")\n    نووسین(\"کەوتیت! کلیک = دووبارە\", ٥٥، ٢٣٠، ٢٦)\n  }\n})\n"
